import{_ as e,c as t,o as p,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易玩辭","description":"周易玩辭 - 周易玩辭","frontmatter":{"title":"周易玩辭","description":"周易玩辭 - 周易玩辭"},"headers":[],"relativePath":"classics/wanci/001.md","filePath":"classics/wanci/001.md"}'),c={name:"classics/wanci/001.md"};function r(i,a,n,_,o,l){return p(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="周易玩辭" tabindex="-1">周易玩辭 <a class="header-anchor" href="#周易玩辭" aria-label="Permalink to “周易玩辭”">​</a></h1><p>欽定四庫全書經部一</p><p>易類提要</p><p>臣 等謹案：周易玩辭十六卷，宋項安世撰。安世字平甫，松陽人。館閣續錄載其淳熙二年同進士出身，紹熙五年除校書郎，慶元元年添差通判池州。陳振孫書錄解題稱為太府卿，則所終之官也。事蹟具宋史本傳。振孫乂稱安世當慶元時，謫居江陵，杜門不出。諸經皆有論說，而易為全書。然據其自述，蓋成於</p><p>嘉泰二年壬戌之秋。自序謂：「易之道四，其實則二，象與辭是也。變則象之進退也，佔則辭之吉凶也。不識其象，何以知其變？不通其辭，何以決其佔？」又自述曰：「安世之所學，蓋伊川程子之書也。今以其所得於易傳者述為此書，而其文無與易傳合者，合則無用述此書矣。」蓋伊川易傳惟闡義理，安世則兼象數而求之。其意欲於程傳之外補所不及，所謂各明一義者也。馬端臨、虞集作序，皆盛相推挹。而近時王懋竑白田雜著中有是書跋，獨排斥甚力，至謂端臨等未觀其書。其殆安世自述中所謂以易傳之文觀我者歟？安世又有項氏家說，其第一卷亦解易，董真卿嘗稱之。世無傳本，今始以永樂大典所載裒合成編，別著於錄。合觀兩書，安世之經學深矣，何可輕詆也。乾隆四十二年二月恭校上。</p><p>總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。周易玩辭序：</p><p>周易玩辭者，江陵項公安世平甫之所著也。其言以為大傳曰：「君子居則觀其象而玩其辭，動則觀其變而玩其佔。」其道雖四，而實則二。變乃象之進退，佔乃辭之吉凶。聖人因象以措辭，後學因辭而測象，是故學易者，舍辭何以哉？項公以其玩於辭而得之者筆於書，使後之學者，因其言皆有以玩於前聖之辭而得焉，此項氏著書之意也。嗟夫！天不言，生聖人而代之言，故曰聖人之精，畫卦以示。聖人之蘊，因卦以發。微卦。聖人之蘊，殆不可悉得而聞。然卦象未有語言，自非明知，何以知之？中古聖人，以其憂患之心，因卦立言，暢於周公，究於孔子，首尾具完，皆所親定。所謂精與蘊者，後世因得以推見焉。今夫生乎千載之下，而仰觀於千載之上，以凡人之資，而欲窺見天與聖人之道，苟得於聖人之一言，即為天之命已矣。況乎三聖人之言，廣大悉備，雖歷世久遠，遭時喪亂，亙千萬古，而與所謂卦畫者，略不可有所磨滅，豈非天乎？後之立言，豈有加於此者？志於學者，誠不可下此而他求己。愚是以深嘆項公之為知言。漢晉以來，治易之師，其言猶有可見，而於四聖人之意，未知其何如也。及乎邵子、周子之生，易道蓋中興焉。邵子以先天心學著為成書，不必麗乎經傳，而極天地之妙，通萬物之情，三聖人以降，未之或先，而學者鮮或知之。周子之圖，亦不必求同於易象，而理則不二。所謂通書者，皆所以通乎易者也。因卦以立辭者，如乾、損、益、家人、睽、復、無妄、蒙、艮之說僅見。如大畜等卦，當時已不得聞。獨賴河南程子親得其宗，以其成德之能事，附於三聖人之書而言之，非直傳注而已也。自其學而推之，以極其至，則天人之際，豈有間哉？蓋嘗聞之，能盡其性者，則能盡人之性；能盡人之性，則能盡物之性。故曰：「知其性，則知天矣。」苟知天矣，則天地之故，鬼神之跡，事物之雜，豈待於考索推測而後通之？故程子有言不盡意者，誠有望於後世學者，自有得於聖人也。朱子發明象佔本義，多約程子之言而精之云爾。故學易之士，於是得其端緒而不差焉。項公實與朱子同時，當時則又有江西陸先生者，各以其學為教。又有聰明文學過人之士，興於永嘉，項公嘗從而問辨諮決焉。其遺文猶有可徵者。朱、項往來之書，至六七而不止，其要旨直以程子「涵養須用敬，進學則在致知」之說以告之。於是項公之學，上不過於高虛，下不陷於功利，而所趨所達，端有定向。然後研精覃思，作為此書。外有以採擇諸家之博聞，內有以及乎象數之通變，奇而不鑿，深而不迂，詳而無餘，約而無闕，庶幾精微之道焉。其書既成，而朱子歿矣。自序其學皆出於程子，而其言則不必皆同也，是可以見其講明之指歸矣。近時學易君子，多有取於其說，豈徒然哉？然而為是學者，自非深求於程朱之說，而有所憤悱於缺塞，則亦不足以知項氏之功也。集之壯歲，至好此書，每取其說，以與朋友講習。今淮西廉訪僉事幹君克莊，好古博雅，學道愛人，嘗以禮學貢於有司而不及奏，有旨俾居成均，勤苦數載，有人所不能堪者。及文宗皇帝臨御，開延閣以待天下之士，乃特召見，得與論思之次，一時謂之得人。持節淮𤲬，至於江上，取是書於篋，俾齊安郡學刻而廣之，蓋嘆乎學者之不多見是書也。不鄙謂集退老林下，庶乎困學之不敢忘，俾敘其說焉。嗚呼！內聖外王之學不明於後世，而為治者以其知力之所及而行之，不無其效。至若上下與天地同流者，則何有哉？昔邵子有言曰：「學於里人而儘裡人之情，學於鄉人而盡鄉人之情，學於國人而盡國人之情，學於古人而盡古人之情，學於天地而盡天地之情。」如此，則可以玩辭觀象而得之，世有斯人也哉！後學虞集謹書。周易玩辭序</p><p>予幼嗜易，祖程傳，宗本義。諸儒訓解中，取平庵項氏玩辭熟讀精思，道德性命之原，開物成務之故，一齣於奇耦往來不窮之變，曰象與佔隨時取義玩辭。可知先生此書，不特有裨於程子七分之傳，當時往復問學朱子之門，其於本義多所發明。惜書成於本義二十年之後，朱子未及見也。集賢初庵傅公以易學經世，被遇殊休，俾其徒黃棠創建精廬，嘉惠後學，經府傳窟中獨缺此書。予過梧翁先生馬公考學，得所藏本，乃鹹淳乙丑禮部貢院所點校，敬鋟諸梓，與朋友共，使家藏而人誦之，予之志也。大德丁未孟秋冷掾徐之祥拜手謹書。周易玩辭序</p><p>易有聖人之道四，變與象居其二焉。自義理之學大明，而變象之說幾晦。先儒欲救其弊，則曰：「聖人當時自可別作一書，明言義理，以詔後世，何用假託卦爻，為此艱深隱晦之辭乎？」愚嘗以為變之說不一，有隨時之變，如彖、象、小象、文言、繋辭，各自一義是也；有逐爻之變，如六九七八、陰陽老少是也；有逐卦之變，如剛柔往來、互體飛伏是也。象之說亦不一，有卦畫之象，陰陽奇耦、三連六斷是也；有大象之象，天地風雷山澤水火是也；有說卦之象，「乾為馬，坤為牛」、「乾為首、坤為腹」之類是也。至簡要者，隨時之變也；至支離者，逐卦之變也；至精微者，卦畫之象也；至瑣碎者，說卦之象也。必研究其簡要精微者，而不拘泥其支離瑣碎者，則曰象曰變，固無非精義至理之所寄也，豈有二哉？平庵項公玩辭之書，義理淵源伊洛，而於象變之際，紬繹尤精，明暢正大，無牽合附會之癖。公嘗謂必徧通五經，而後歸老於易。且自言窺其門牆，而未極其穾奧，今將盡心焉。則是書必暮年所著，家有善本，先公嘗熟復而手校之。方塘徐君掌教初庵，以是書鋟梓學舍，俾贅語其編尾，輒誦所聞。大德丁未菊月後學馬端臨謹書。周易玩辭序</p><p>序曰：大傳曰：「君子居則觀其象而玩其辭，動則觀其變而玩其佔。」讀易之法，盡於此矣。易之道四，其實則二，象與辭是也。變則象之進退也，佔則辭之吉凶也。不識其象，何以知其變？不通其辭，何以決其佔？然而聖人因象以措辭，後學因辭而測象，則今之讀易，所當反覆紬繹、精思而深味者，莫辭若也。於是作周易玩辭。宋慶元四年歲次戊午秋九月己未，江陵項安世述。周易上篇六卷，周易下篇六卷，繫辭兩卷，說卦一卷，序卦、雜卦一卷。</p><p>嘉泰二年壬戌之秋，重修周易玩辭十六卷。章句粗定，因自嘆曰：「安世之所學，蓋伊川程子之書也。」程子平生所著，獨易傳為全書，安世受而讀之三十年矣。今以其所得於易傳者述為此書，而其文無與易傳合者，合則無用述此書矣。世之友朋以易傳之理觀吾書，本末條貫，無一不本於易傳者；以易傳之文觀吾書，則未免有使西河之民疑汝於夫子之怒。知我者，此書也；罪我者，此書也。九月丙午，安世謹書。</p>',11)])])}const f=e(c,[["render",r]]);export{m as __pageData,f as default};
